mapper.select:
SELECT APP.ID ID,APP.RECRUIT_ID RECRUITID, PARK.PARK_NAME, APP.PARK_ID PARKID,APP.NAME,APP.SEX,APP.AGE,APP.APPLY_DATE APPLYDATE,
APP.PHONE,APP.STATUS,APP.CREATE_TIME CREATETIME,RE.JOB_NAME JOBNAME,RE.JCHE_NAME JCHENAME
FROM  SMT_APPLICATION APP
    INNER JOIN SMT_PARK PARK ON APP.PARK_ID=PARK.ID
    INNER JOIN SMT_RECRUITMENT RE ON APP.RECRUIT_ID=RE.ID
WHERE  APP.IS_DELETE=0

	AND APP.PARK_ID =#{query.parkId}


	AND APP.DEP_ID =#{query.depId}


	AND APP.COMP_ID =#{query.compId}


	AND RE.JOB_NAME LIKE CONCAT(CONCAT('%',#{query.jobName}),'%')


	AND APP.STATUS =#{query.status}


	AND APP.NAME LIKE CONCAT(CONCAT('%',#{query.name}),'%')


	AND APP.PHONE LIKE  CONCAT(CONCAT('%',#{query.phone}),'%')


	AND RE.JOB_ID =#{query.jobId}


	AND APP.AGE >= #{query.startAge}


	AND APP.AGE  <  #{query.endAge}


		and app.apply_date between to_date(#{query.startTime},'yyyy-mm-dd hh24:mi:ss') and to_date(#{query.endTime},'yyyy-mm-dd hh24:mi:ss')


	AND APP.PARK_ID IN

		#{tempId}


ORDER BY APP.APPLY_DATE DESC,APP.CREATE_TIME DESC

	SELECT APP.ID ,APP.NAME,APP.SEX,APP.AGE,PARK.PARK_NAME,RE.EDUCATION,APP.FACE_PIC_ID,RE.DEP_NAME,RE.JCHE_NAME,
	APP.APPLY_DATE,APP.STATUS ,RE.JOB_NAME,RE.PARK_ID   FROM  SMT_APPLICATION APP
	INNER JOIN SMT_RECRUITMENT RE ON APP.RECRUIT_ID=RE.ID
	INNER JOIN SMT_PARK PARK ON RE.PARK_ID=PARK.ID
	WHERE  IS_DELETE=0  AND   APP.STATUS <> -1 

	AND APP.STATUS =#{query.applyState}


	AND APP.NAME LIKE CONCAT(CONCAT('%',#{query.applicantName}),'%')



	AND APP.PHONE LIKE CONCAT(CONCAT('%',#{query.applicantMobile}),'%')



	AND APP.RECRUIT_ID =#{query.jobId}


	AND APP.AGE BETWEEN #{query.ageStart} AND #{query.ageEnd}


	AND APP.SEX =#{query.gender}


	AND APP.park_id =#{query.parkId}



	AND RE.JCHE_ID in

      #{id}



	AND APP.PARK_ID in

      #{id}




	ORDER BY  APP.AGE  DESC


	ORDER BY  APP.AGE  ASC



	ORDER BY  APP.APPLY_DATE  DESC


	ORDER BY  APP.APPLY_DATE  ASC
